#include <cstddef>
#include <cstdint>
#include <limits>
static constexpr std::size_t NMAX=8, INPUTMAX=1+NMAX*NMAX, ADJUSTMAX=2048;
static int first_assignments(std::int64_t* a,std::uint8_t* mark,std::size_t n){for(std::size_t x=0;x<n*n;++x)mark[x]=0;std::size_t total=0;
 for(;;){std::size_t made=0;for(std::size_t i=0;i<n;++i){std::size_t cnt=0,sel=0;for(std::size_t j=0;j<n;++j)if(a[i*n+j]==0&&mark[i*n+j]==0){++cnt;sel=j;}if(cnt==1){++made;++total;mark[i*n+sel]=1;for(std::size_t k=0;k<n;++k)if(k!=i&&a[k*n+sel]==0)mark[k*n+sel]=2;}}
 for(std::size_t j=0;j<n;++j){std::size_t cnt=0,sel=0;for(std::size_t i=0;i<n;++i)if(a[i*n+j]==0&&mark[i*n+j]==0){++cnt;sel=i;}if(cnt==1){++made;++total;mark[sel*n+j]=1;for(std::size_t k=0;k<n;++k)if(k!=j&&a[sel*n+k]==0)mark[sel*n+k]=2;}}if(!made)break;}
 if(total==n)return static_cast<int>(total);for(std::size_t i=0;i<n;++i){std::size_t sel=n;for(std::size_t j=0;j<n;++j)if(a[i*n+j]==0&&mark[i*n+j]==0){sel=j;break;}if(sel<n){mark[i*n+sel]=1;++total;for(std::size_t k=0;k<n;++k)if(k!=sel&&a[i*n+k]==0)mark[i*n+k]=2;for(std::size_t k=0;k<n;++k)if(k!=i&&a[k*n+sel]==0)mark[k*n+sel]=2;}}return static_cast<int>(total);}
static bool second_assignments(std::int64_t* a,const std::uint8_t* mark,std::size_t n){std::uint8_t rows[NMAX]{},cols[NMAX]{};for(std::size_t i=0;i<n;++i){bool has=false;for(std::size_t j=0;j<n;++j)if(mark[i*n+j]==1){has=true;break;}rows[i]=has?0:1;}
 for(;;){std::size_t newrows=0;for(std::size_t i=0;i<n;++i)if(rows[i])for(std::size_t j=0;j<n;++j)if(a[i*n+j]==0)cols[j]=1;for(std::size_t j=0;j<n;++j)if(cols[j])for(std::size_t i=0;i<n;++i)if(mark[i*n+j]==1&&rows[i]!=1){rows[i]=1;++newrows;}if(!newrows)break;}
 auto smallest=std::numeric_limits<std::int64_t>::max();for(std::size_t i=0;i<n;++i)if(rows[i])for(std::size_t j=0;j<n;++j)if(!cols[j]&&a[i*n+j]<smallest)smallest=a[i*n+j];if(smallest==std::numeric_limits<std::int64_t>::max())return false;for(std::size_t i=0;i<n;++i)for(std::size_t j=0;j<n;++j){if(rows[i]&&!cols[j])a[i*n+j]-=smallest;else if(!rows[i]&&cols[j])a[i*n+j]+=smallest;}return true;}
extern "C" std::int64_t nbench_resource_assignment(const std::int64_t* values,std::size_t length,std::uint8_t* output,std::size_t capacity){if(!values||length<2||length>INPUTMAX+1)return -1;auto rn=values[0];if(rn<1||rn>static_cast<std::int64_t>(NMAX)||length!=1+static_cast<std::size_t>(rn*rn))return -1;auto n=static_cast<std::size_t>(rn);std::int64_t a[NMAX*NMAX]{};for(std::size_t i=0;i<n*n;++i){if(values[i+1]<0||values[i+1]>1000)return -1;a[i]=values[i+1];}
 for(std::size_t i=0;i<n;++i){auto m=a[i*n];for(std::size_t j=1;j<n;++j)if(a[i*n+j]<m)m=a[i*n+j];for(std::size_t j=0;j<n;++j)a[i*n+j]-=m;}for(std::size_t j=0;j<n;++j){auto m=a[j];for(std::size_t i=1;i<n;++i)if(a[i*n+j]<m)m=a[i*n+j];if(m)for(std::size_t i=0;i<n;++i)a[i*n+j]-=m;}
 std::uint8_t mark[NMAX*NMAX]{};bool done=false;for(std::size_t k=0;k<=ADJUSTMAX;++k){if(first_assignments(a,mark,n)==static_cast<int>(n)){done=true;break;}if(!second_assignments(a,mark,n))return -1;}if(!done)return -1;std::size_t columns[NMAX]{};bool seen[NMAX]{};for(std::size_t i=0;i<n;++i){std::size_t col=n;for(std::size_t j=0;j<n;++j)if(mark[i*n+j]==1){if(col!=n)return -1;col=j;}if(col==n||seen[col])return -1;columns[i]=col;seen[col]=true;}const auto bytes=n*4;if(!output||capacity<bytes)return -2;for(std::size_t i=0;i<n;++i){auto x=static_cast<std::uint32_t>(columns[i]);for(std::size_t b=0;b<4;++b)output[4*i+b]=static_cast<std::uint8_t>(x>>(8*b));}return static_cast<std::int64_t>(bytes);}
